export * as ModelPicker from './model-picker.tsx';
export type {
  ContentProps as ModelPickerContentProps,
  ItemOwnProps as ModelPickerItemOwnProps,
  ItemProps as ModelPickerItemProps,
} from './model-picker.tsx';

@layer hj.components {
  /* Customise: --hj-model-picker-width (popup width) */
  .hj-model-picker-trigger {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: calc(4px * var(--hj-density));
    max-width: 220px;
    height: calc(32px * var(--hj-density-size));
    padding: 0 calc(8px * var(--hj-density)) 0 calc(12px * var(--hj-density));
    border: 0;
    border-radius: var(--hj-radius-pill);
    background: transparent;
    color: var(--hj-fg-dim);
    font: 600 13px / 1 var(--hj-font-sans);
    cursor: pointer;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  .hj-model-picker-trigger::before {
    content: '';
    position: absolute;
    inset: -6px 0;
  }
  .hj-model-picker-trigger:hover,
  .hj-model-picker-trigger[data-popup-open] {
    background: color-mix(in srgb, var(--hj-fg) 7%, transparent);
    color: var(--hj-fg);
  }
  .hj-model-picker-trigger:active:not([data-disabled]) {
    transform: scale(var(--hj-press));
    transition-duration: 70ms;
  }
  .hj-model-picker-trigger[data-disabled] {
    opacity: 0.4;
    cursor: not-allowed;
  }
  .hj-model-picker-value {
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }
  .hj-model-picker-chevron {
    display: inline-flex;
    flex: none;
    font-size: 15px;
    line-height: 0;
    color: var(--hj-fg-mute);
    transition: transform var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle);
  }
  .hj-model-picker-chevron svg {
    width: 1em;
    height: 1em;
  }
  .hj-model-picker-trigger[data-popup-open] .hj-model-picker-chevron {
    transform: rotate(180deg);
  }

  .hj-model-picker-positioner {
    z-index: var(--hj-z-popover);
    outline: 0;
  }
  .hj-model-picker-popup {
    width: max(var(--anchor-width), var(--hj-model-picker-width, 320px));
    max-height: var(--available-height);
    padding: calc(6px * var(--hj-density));
    overflow-y: auto;
    border: 1px solid var(--hj-line);
    border-radius: var(--hj-radius-md);
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface-2);
    box-shadow: var(--hj-shadow-lift);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    outline: 0;
    transform-origin: var(--transform-origin);
    transition:
      transform var(--hj-dur-snappy) var(--hj-ease-snappy),
      opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  /* Grows from the trigger; leaves faster than it came. */
  .hj-model-picker-popup[data-starting-style],
  .hj-model-picker-popup[data-ending-style] {
    opacity: 0;
    transform: scale(0.96);
  }
  .hj-model-picker-popup[data-ending-style] {
    transition-duration: var(--hj-dur-fast);
    transition-timing-function: var(--hj-ease-out);
  }
  .hj-model-picker-list {
    display: grid;
    gap: 2px;
    outline: 0;
  }

  .hj-model-picker-item {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) 16px;
    column-gap: calc(10px * var(--hj-density));
    row-gap: 2px;
    padding: calc(9px * var(--hj-density)) calc(10px * var(--hj-density))
      calc(9px * var(--hj-density)) calc(12px * var(--hj-density));
    border-radius: var(--hj-radius-sm);
    corner-shape: var(--hj-corner-shape, round);
    outline: 0;
    cursor: default;
    user-select: none;
    transition: background-color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-model-picker-item[data-highlighted] {
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
  }
  .hj-model-picker-item:active {
    opacity: var(--hj-press-opacity);
  }
  .hj-model-picker-item[data-disabled] {
    opacity: 0.4;
  }
  .hj-model-picker-item-head {
    display: flex;
    align-items: center;
    gap: calc(6px * var(--hj-density));
    min-width: 0;
  }
  .hj-model-picker-item-name {
    font-size: 14px;
    font-weight: 600;
    letter-spacing: -0.01em;
  }
  .hj-model-picker-item[data-selected] .hj-model-picker-item-name {
    color: var(--hj-accent-text);
  }
  .hj-model-picker-item-provider {
    font-size: 12px;
    color: var(--hj-fg-mute);
  }
  .hj-model-picker-badge {
    display: inline-flex;
    align-items: center;
    height: 17px;
    padding: 0 calc(6px * var(--hj-density));
    border-radius: var(--hj-radius-pill);
    background: color-mix(in srgb, var(--hj-fg) 7%, transparent);
    color: var(--hj-fg-dim);
    font: 500 10px / 1 var(--hj-font-mono);
    letter-spacing: 0.02em;
  }
  .hj-model-picker-item-description {
    grid-column: 1;
    font-size: 12.5px;
    line-height: 17px;
    color: var(--hj-fg-mute);
  }
  .hj-model-picker-item-indicator {
    grid-column: 2;
    grid-row: 1;
    align-self: center;
    display: inline-flex;
    font-size: 16px;
    line-height: 0;
    color: var(--hj-accent-text);
  }
  .hj-model-picker-item-indicator svg {
    width: 1em;
    height: 1em;
  }

  .hj-model-picker-group-label {
    padding: calc(8px * var(--hj-density)) calc(12px * var(--hj-density))
      calc(4px * var(--hj-density));
    font: var(--hj-type-eyebrow);
    letter-spacing: var(--hj-tracking-eyebrow);
    text-transform: uppercase;
    color: var(--hj-fg-mute);
  }
  .hj-model-picker-separator {
    height: 1px;
    margin: calc(4px * var(--hj-density)) calc(8px * var(--hj-density));
    background: var(--hj-line);
  }
}

'use client';
import { Select as Base } from '@base-ui/react/select';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { part } from '../../system/part.tsx';
import type { HanjiPart } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';
import { ThemeScope } from '../../system/theme.tsx';

/** Base UI Select.Root: value, onValueChange, items (value → label for the trigger), disabled. */
export const Root: typeof Base.Root = Base.Root;
export const Value: HanjiPart<typeof Base.Value> = part(
  Base.Value,
  'ModelPicker.Value',
  'hj-model-picker-value',
);
export const Positioner: HanjiPart<typeof Base.Positioner> = part(
  Base.Positioner,
  'ModelPicker.Positioner',
  'hj-model-picker-positioner',
);
export const Popup: HanjiPart<typeof Base.Popup> = part(
  Base.Popup,
  'ModelPicker.Popup',
  'hj-model-picker-popup',
);
export const List: HanjiPart<typeof Base.List> = part(
  Base.List,
  'ModelPicker.List',
  'hj-model-picker-list',
);
export const Group: HanjiPart<typeof Base.Group> = part(
  Base.Group,
  'ModelPicker.Group',
  'hj-model-picker-group',
);
export const GroupLabel: HanjiPart<typeof Base.GroupLabel> = part(
  Base.GroupLabel,
  'ModelPicker.GroupLabel',
  'hj-model-picker-group-label',
);
export const Separator: HanjiPart<typeof Base.Separator> = part(
  Base.Separator,
  'ModelPicker.Separator',
  'hj-model-picker-separator',
);

/** Portals to `<body>` and keeps the nearest `<Theme>`. */
export function Portal({ children, ...props }: Base.Portal.Props): React.ReactElement {
  return (
    <Base.Portal {...props}>
      <ThemeScope>{children}</ThemeScope>
    </Base.Portal>
  );
}

/** The current model as a quiet pill with a chevron. Children replace the default `<Value />`. */
export function Trigger(props: Base.Trigger.Props): React.ReactElement {
  const config = useHanjiConfig();
  const { className, children, ...rest } = withDefaults(config, 'ModelPicker.Trigger', props);
  return (
    <Base.Trigger
      {...rest}
      className={cls(config, 'ModelPicker.Trigger', 'hj-model-picker-trigger', className)}
    >
      {children ?? <Value />}
      <Base.Icon className={config.unstyled ? undefined : 'hj-model-picker-chevron'}>
        {config.icons.chevronDown}
      </Base.Icon>
    </Base.Trigger>
  );
}

export interface ContentOwnProps {
  /** @default 6 */
  sideOffset?: number;
  /** @default 'start' */
  align?: 'start' | 'center' | 'end';
  /** @default 'top' — the composer usually sits at the bottom of the screen. */
  side?: 'top' | 'bottom';
}
export interface ContentProps extends ContentOwnProps, Base.Popup.Props {}

/** Shorthand: Portal + Positioner + Popup + List. Opens above the trigger by default. */
export function Content({
  sideOffset = 6,
  align = 'start',
  side = 'top',
  children,
  ...popup
}: ContentProps): React.ReactElement {
  return (
    <Portal>
      <Positioner sideOffset={sideOffset} align={align} side={side} alignItemWithTrigger={false}>
        <Popup {...popup}>
          <List>{children}</List>
        </Popup>
      </Positioner>
    </Portal>
  );
}

export interface ItemOwnProps {
  /** The model's display name — also its text for typeahead. */
  name: string;
  /** Who makes or serves it. */
  provider?: string;
  /** One line on what it's good at, with a number if you have one. */
  description?: string;
  /** Short capability tags: `fast`, `reasoning`, `vision`, `beta`… */
  badges?: readonly string[];
}
export interface ItemProps extends ItemOwnProps, Omit<Base.Item.Props, 'children'> {}

/** One model: name, provider, badges on the first line; the capability line under it. */
export function Item(props: ItemProps): React.ReactElement {
  const config = useHanjiConfig();
  const { name, provider, description, badges, className, ...rest } = withDefaults(
    config,
    'ModelPicker.Item',
    props,
  );
  const s = !config.unstyled;
  return (
    <Base.Item
      {...rest}
      className={cls(config, 'ModelPicker.Item', 'hj-model-picker-item', className)}
    >
      <span className={s ? 'hj-model-picker-item-head' : undefined}>
        <Base.ItemText className={s ? 'hj-model-picker-item-name' : undefined}>
          {name}
        </Base.ItemText>
        {provider ? (
          <span className={s ? 'hj-model-picker-item-provider' : undefined}>{provider}</span>
        ) : null}
        {badges?.map((b) => (
          <span key={b} className={s ? 'hj-model-picker-badge' : undefined} data-badge={b}>
            {b}
          </span>
        ))}
      </span>
      {description ? (
        <span className={s ? 'hj-model-picker-item-description' : undefined}>{description}</span>
      ) : null}
      <Base.ItemIndicator className={s ? 'hj-model-picker-item-indicator' : undefined}>
        {config.icons.check}
      </Base.ItemIndicator>
    </Base.Item>
  );
}
